import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "./Navbar";
import { useLocation } from "react-router-dom";

function Feedback() {
  const location = useLocation();
  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "Event";

  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [feedbacks, setFeedbacks] = useState([]);

  useEffect(() => {
    fetchFeedbacks();
  }, [eventId]);

  const fetchFeedbacks = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/feedback/${eventId}`);
      setFeedbacks(res.data);
    } catch (err) {
      console.log(err);
    }
  };

  const submitFeedback = async () => {
    try {
      await axios.post("http://localhost:5000/feedback", {
        user_id: 1, // Replace with actual logged-in user ID
        event_id: eventId,
        rating,
        comment,
      });

      alert("Feedback submitted!");
      setComment("");
      fetchFeedbacks();
    } catch (err) {
      console.log(err);
      alert("Failed to submit feedback");
    }
  };

  return (
    <div>
      <Navbar />
      <div style={{ padding: "20px", maxWidth: "600px", margin: "auto" }}>
        <h2>Feedback for {eventName}</h2>

        <div>
          <label>Rating:</label>
          <select value={rating} onChange={(e) => setRating(Number(e.target.value))}>
            {[1, 2, 3, 4, 5].map((r) => (
              <option key={r} value={r}>{r}</option>
            ))}
          </select>
        </div>

        <div>
          <label>Comment:</label>
          <textarea value={comment} onChange={(e) => setComment(e.target.value)} />
        </div>

        <button onClick={submitFeedback}>Submit Feedback</button>

        <hr />

        <h3>All Feedbacks</h3>
        {feedbacks.map((f) => (
          <div key={f.id} style={{ border: "1px solid #ccc", margin: "10px 0", padding: "10px" }}>
            <p><b>{f.user_name}</b> rated: {f.rating} / 5</p>
            <p>{f.comment}</p>
            <p><i>{new Date(f.created_at).toLocaleString()}</i></p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Feedback;
